pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // The reference's owned() has require(msg.sender == owner), which passes (owner is address(0) != msg.sender, so revert). Wait, the reference: require(msg.sender == owner) fails when msg.sender != owner → reference reverts.
        // The bug: require(msg.sender != owner) passes when msg.sender != owner → bug does not revert.
        // We want the assertion that the reference reverts and bug does not.
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // reference reverts (ok = false), bug passes (ok = true)
        assertTrue(ok == false); // this passes on reference (false == false) and fails on bug (false != true)
    }
}

